                        p += 1;
                        continue :dfa 42;
                    },
                    else => {},
                };
                break :dfa;
            },
            42 => {
                acc = 6;
                accEnd = p;
                if (p < n) switch (src[p]) {
                    '\'' => {
                        p += 1;
                        continue :dfa 41;
                    },
                    else => {},
                };
                self.beg = 0;
                self.pos = @intCast(p);
                return .{ .cat = .@"string_sq", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            49 => {
                while (p < n and src[p] -% '0' <= 9) p += 1;
                self.beg = 0;
                self.pos = @intCast(p);
                return .{ .cat = .@"real", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            51 => {
                if (p < n) switch (src[p]) {
                    '0'...'9' => {
                        p += 1;
                        continue :dfa 49;
                    },
                    else => {},
                };
                break :dfa;
            },
            52 => {
                if (p < n) switch (src[p]) {
                    '0'...'1' => {
                        p += 1;
                        continue :dfa 67;
                    },
                    else => {},
                };
                break :dfa;
            },
            53 => {
                if (p < n) switch (src[p]) {
                    '0'...'7' => {
                        p += 1;
                        continue :dfa 68;
                    },
                    else => {},
                };
                break :dfa;
            },
            54 => {
                if (p < n) switch (src[p]) {
                    '0'...'9', 'A'...'F', 'a'...'f' => {
                        p += 1;
                        continue :dfa 69;
                    },
                    else => {},
                };
                break :dfa;
            },
            67 => {
                while (p < n and src[p] -% '0' <= 1) p += 1;
                self.beg = 0;
                self.pos = @intCast(p);
                return .{ .cat = .@"integer", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            68 => {
                while (p < n and src[p] -% '0' <= 7) p += 1;
                self.beg = 0;
                self.pos = @intCast(p);
                return .{ .cat = .@"integer", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            69 => {
                while (p < n and cls1[src[p]]) p += 1;
                self.beg = 0;
                self.pos = @intCast(p);
                return .{ .cat = .@"integer", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            else => unreachable,
        }
        switch (acc) {
            56 => {
                self.beg = 0;
                p = accEnd;
                self.pos = @intCast(p);
                return .{ .cat = .@"err", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            11 => {
                self.beg = 0;
                p = accEnd;
                self.pos = @intCast(p);
                return .{ .cat = .@"integer", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            6 => {
                self.beg = 0;
                p = accEnd;
                self.pos = @intCast(p);
                return .{ .cat = .@"string_sq", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            else => {},
        }
        self.beg = 0;
        self.pos = @intCast(start + 1);
        return .{ .cat = .@"err", .pre = pre, .pos = @intCast(start), .len = 1 };
    }
};

pub const Lexer = if (@hasDecl(zag, "Lexer")) zag.Lexer else BaseLexer;

// =============================================================================
// Tag Enum (re-exported from language module)
// =============================================================================
pub const Tag = zag.Tag;

// =============================================================================
// S-Expression (AST Node) - 5 Clean Variants
// =============================================================================

pub const Sexp = union(enum) {
    nil:  void,                                        // Empty (nothing)
    tag:  Tag,                                         // Semantic type (1 byte)
    src:  struct { pos: u32, len: u16, id: u16 },      // Source ref + identity (8 bytes)
    str:  []const u8,                                  // Embedded string (16 bytes)
    list: []const Sexp,                                // Compound: (tag child1 ...)

    /// Get token text from source
    pub fn getText(self: Sexp, source: []const u8) []const u8 {
        return switch (self) {
            .src => |s| source[s.pos..][0..s.len],
            .str => |s| s,
            else => "",
        };
    }

    /// Format for debug output
    pub fn write(self: Sexp, source: []const u8, w: anytype) !void {
        switch (self) {
            .nil => try w.writeAll("_"),
            .tag => |t| try w.print("{s}", .{@tagName(t)}),
            .src => |s| try w.print("{s}", .{source[s.pos..][0..s.len]}),
            .str => |s| try w.print("\"{s}\"", .{s}),
            .list => |items| {
                try w.writeAll("(");
                for (items, 0..) |item, i| {
                    if (i > 0) try w.writeAll(" ");
                    try item.write(source, w);
                }
                try w.writeAll(")");
            },
        }
    }
};

// =============================================================================
// PARSER
// =============================================================================

pub const BaseParser = struct {
    arena: std.heap.ArenaAllocator,
    lexer: Lexer,
    source: []const u8,
    current: Token,
    injectedToken: ?u16 = null,
    lastMatchedId: u16 = 0,

    stateStack: std.ArrayListUnmanaged(u16) = .empty,
    valueStack: std.ArrayListUnmanaged(Sexp) = .empty,
    /// Spare capacity of the lists `keepList` returned, by address.
    listSpare: std.AutoHashMapUnmanaged(usize, ListSpare) = .empty,

    const ListSpare = struct { len: usize, capacity: usize };

    pub fn init(backingAllocator: std.mem.Allocator, source: []const u8) BaseParser {
        var p = BaseParser{
            .arena = std.heap.ArenaAllocator.init(backingAllocator),
            .lexer = Lexer.init(source),
            .source = source,
            .current = undefined,
        };
        p.current = p.lexer.next();
        return p;
    }

    pub fn deinit(self: *BaseParser) void {
        self.arena.deinit();
    }

    fn allocator(self: *BaseParser) std.mem.Allocator {
        return self.arena.allocator();
    }

    pub fn printError(self: *BaseParser) void {
        const pos: usize = @min(self.current.pos, self.source.len);
        var line: usize = 1;
        var col: usize = 1;
        var i: usize = 0;
        while (i < pos) : (i += 1) {
            if (self.source[i] == '\n') {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        std.debug.print("Parse error at line {d}, column {d}: unexpected {s}\n", .{
            line,
            col,
            @tagName(self.current.cat),
        });
    }

    fn doParse(self: *BaseParser, startSym: u16) !Sexp {
        const startState = getStartState(startSym);
        self.stateStack.clearRetainingCapacity();
        self.valueStack.clearRetainingCapacity();
        try self.stateStack.append(self.allocator(), startState);

        while (true) {
            const state = self.stateStack.getLast();
            const sym = if (self.injectedToken) |inj| inj else self.tokenToSymbol(self.current);
            var action = getAction(state, sym);

            // X "c" check: if reducing and next char matches with pre==0, shift instead
            if (action < -1 and self.current.pre == 0 and self.current.pos < self.source.len) {
                if (getImmediateShift(state, self.source[self.current.pos])) |shiftTarget| {
                    action = shiftTarget;
                }
            }

            if (action == 0) {
                return error.ParseError;
            } else if (action == -1) {
                return self.valueStack.getLast();
            } else if (action > 0) {
                // Shift
                if (self.injectedToken != null) {
                    try self.valueStack.append(self.allocator(), .nil);
                    self.injectedToken = null;
                } else {
                    try self.valueStack.append(self.allocator(), .{ .src = .{
                        .pos = self.current.pos,
                        .len = self.current.len,
                        .id  = if (self.lastMatchedId != 0) self.lastMatchedId else self.lexer.base.aux,
                    } });
                    self.lastMatchedId = 0;
                    self.lexer.base.aux = 0;
                    self.current = self.lexer.next();
                }
                try self.stateStack.append(self.allocator(), @intCast(action));
            } else {
                // Reduce
                const ruleId: u16 = @intCast(-action - 2);
                var pass: [maxArgs]Sexp = undefined;
                const len = ruleLen[ruleId];
                for (0..len) |i| {
                    pass[len - 1 - i] = self.valueStack.pop().?;
                    _ = self.stateStack.pop();
                }

                const result = self.executeAction(ruleId, pass[0..len]);

                if (isAcceptRule(ruleId)) return result;

                try self.valueStack.append(self.allocator(), result);

                const gotoState = self.stateStack.getLast();
                const next = getAction(gotoState, ruleLhs[ruleId]);
                if (next <= 0) return error.ParseError;
                try self.stateStack.append(self.allocator(), @intCast(next));
            }
        }
    }

    /// Spread list helper: [head, ...tail]
    fn spreadList(self: *BaseParser, head: Sexp, tail: Sexp) Sexp {
        var out: std.ArrayListUnmanaged(Sexp) = .empty;
        out.append(self.allocator(), head) catch return .nil;
        if (tail == .list) for (tail.list) |item| out.append(self.allocator(), item) catch return .nil;
        return .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} };
    }

    /// Spread only: [...tail]
    fn spreadOnly(self: *BaseParser, tail: Sexp) Sexp {
        var out: std.ArrayListUnmanaged(Sexp) = .empty;
        if (tail == .list) for (tail.list) |item| out.append(self.allocator(), item) catch return .nil;
        return .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} };
    }

    /// Default list handler
    fn list(self: *BaseParser, pass: []Sexp) Sexp {
        if (pass.len == 0) return .nil;
        if (pass.len == 1) return pass[0];
        var out: std.ArrayListUnmanaged(Sexp) = .empty;
        for (pass) |v| out.append(self.allocator(), v) catch return .nil;
        return .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} };
    }

    /// Start a list holding the items of `base` (a list, else
    /// nothing) for an action that appends to it. A list from
    /// `keepList` is reused with its spare capacity, so a
    /// left-recursive list grows in amortized O(1) per element.
    fn extendList(self: *BaseParser, base: Sexp) !std.ArrayListUnmanaged(Sexp) {
        if (base != .list) return .empty;
        const items = base.list;
        if (items.len > 0) if (self.listSpare.get(@intFromPtr(items.ptr))) |spare| {
            if (spare.len == items.len) {
                _ = self.listSpare.remove(@intFromPtr(items.ptr));
                return .{ .items = @constCast(items), .capacity = spare.capacity };
            }
        };
        var out: std.ArrayListUnmanaged(Sexp) = .empty;
        try out.appendSlice(self.allocator(), items);
        return out;
    }

    /// Finish a list from `extendList`, recording its spare capacity.
    fn keepList(self: *BaseParser, out: *std.ArrayListUnmanaged(Sexp)) Sexp {
        if (out.items.len > 0 and out.capacity > out.items.len) {
            self.listSpare.put(self.allocator(), @intFromPtr(out.items.ptr), .{
                .len = out.items.len,
                .capacity = out.capacity,
            }) catch {};
        }
        return .{ .list = out.items };
    }

    /// Build S-expression: (tag items...) with trailing nil trimming
    inline fn sexp(self: *BaseParser, comptime tag: Tag, items: []const Sexp) Sexp {
        if (items.len == 0) {
            const result = self.allocator().alloc(Sexp, 1) catch return .nil;
            result[0] = .{ .tag = tag };
            return .{ .list = result };
        }
        var len = items.len;
        while (len > 0 and items[len - 1] == .nil) len -= 1;
        const result = self.allocator().alloc(Sexp, len + 1) catch return .nil;
        result[0] = .{ .tag = tag };
        if (len > 0) @memcpy(result[1..][0..len], items[0..len]);
        return .{ .list = result };
    }

    /// Build S-expression: (tag ...spread) - tag + spread items
    inline fn sexpSpread(self: *BaseParser, comptime tag: Tag, spread: Sexp) Sexp {
        const items = if (spread == .list) spread.list else &[_]Sexp{};
        var len = items.len;
        while (len > 0 and items[len - 1] == .nil) len -= 1;
        const result = self.allocator().alloc(Sexp, len + 1) catch return .nil;
        result[0] = .{ .tag = tag };
        if (len > 0) @memcpy(result[1..][0..len], items[0..len]);
        return .{ .list = result };
    }

    /// Build S-expression: (tag pos ...spread) - tag + position + spread items
    inline fn sexpPosSpread(self: *BaseParser, comptime tag: Tag, pos: Sexp, spread: Sexp) Sexp {
        const items = if (spread == .list) spread.list else &[_]Sexp{};
        var len = items.len;
        while (len > 0 and items[len - 1] == .nil) len -= 1;
        const skipPos = (pos == .nil and len == 0);
        const total = if (skipPos) 1 else len + 2;
        const result = self.allocator().alloc(Sexp, total) catch return .nil;
        result[0] = .{ .tag = tag };
        if (!skipPos) {
            result[1] = pos;
            if (len > 0) @memcpy(result[2..][0..len], items[0..len]);
        }
        return .{ .list = result };
    }

    fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
        return switch (ruleId) {
            0 => self.sexpSpread(.@"module", pass[0]),
            1 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), pass[0]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} }; },
            2 => blk: { var out = self.extendList(pass[0]) catch break :blk .nil; out.append(self.allocator(), pass[2]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk self.keepList(&out); },
            3 => pass[0],
            4 => self.list(pass),
            5 => self.list(pass),
            6 => self.list(pass),
            7 => self.list(pass),
            8 => self.sexp(.@"labeled", &.{pass[1], pass[2]}),
            9 => self.list(pass),
            10 => self.sexp(.@"extern_const", &.{pass[2], pass[4]}),
            11 => self.sexp(.@"extern_var", &.{pass[1], pass[3]}),
            12 => self.sexp(.@"zig", &.{pass[1]}),
            13 => self.sexp(.@"zig", &.{pass[1]}),
            14 => self.list(pass),
            15 => self.sexp(.@"pub", &.{pass[1]}),
            16 => self.sexp(.@"extern", &.{pass[1]}),
            17 => self.sexp(.@"export", &.{pass[1]}),
            18 => self.sexp(.@"packed", &.{pass[1]}),
            19 => self.sexp(.@"callconv", &.{pass[1], pass[2]}),
            20 => self.list(pass),
            21 => self.list(pass),
            22 => self.list(pass),
            23 => self.list(pass),
            24 => self.list(pass),
            25 => self.list(pass),
            26 => self.list(pass),
            27 => self.list(pass),
            28 => self.sexpSpread(.@"block", pass[1]),
            29 => self.sexp(.@"block", &.{}),
            30 => self.sexp(.@"fun", &.{pass[1], pass[2], pass[3], pass[4]}),
            31 => self.sexp(.@"fun", &.{pass[1], pass[2], .nil, pass[3]}),
            32 => self.sexp(.@"fun", &.{pass[1], .nil, pass[2], pass[3]}),
            33 => self.sexp(.@"fun", &.{pass[1], .nil, .nil, pass[2]}),
            34 => self.sexp(.@"sub", &.{pass[1], pass[2], .nil, pass[3]}),
            35 => self.sexp(.@"sub", &.{pass[1], .nil, .nil, pass[2]}),
            36 => self.sexp(.@"use", &.{pass[1]}),
            37 => self.sexp(.@"type", &.{pass[1], pass[3]}),
            38 => self.sexp(.@"test", &.{pass[1], pass[2]}),
            39 => self.sexp(.@"opaque", &.{pass[1]}),
            40 => self.sexpPosSpread(.@"enum", pass[1], pass[3]),
            41 => self.sexpPosSpread(.@"errors", pass[1], pass[3]),
            42 => self.sexpPosSpread(.@"struct", pass[1], pass[3]),
            43 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), pass[0]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} }; },
            44 => blk: { var out = self.extendList(pass[0]) catch break :blk .nil; out.append(self.allocator(), pass[2]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk self.keepList(&out); },
            45 => pass[0],
            46 => self.list(pass),
            47 => self.sexp(.@"valued", &.{pass[0], pass[2]}),
            48 => self.list(pass),
            49 => self.list(pass),
            50 => self.sexp(.@"comptime_param", &.{pass[1], pass[3]}),
            51 => pass[0],
            52 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@":" }) catch break :blk .nil; out.append(self.allocator(), pass[0]) catch break :blk .nil; out.append(self.allocator(), pass[2]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} }; },
            53 => self.sexp(.@"aligned", &.{pass[0], pass[2], pass[4]}),
            54 => self.sexp(.@"default", &.{pass[0], pass[2], pass[4]}),
            55 => self.spreadList(pass[0], pass[1]),
            56 => self.spreadList(pass[1], pass[2]),
            57 => .{ .list = &[_]Sexp{} },
            58 => blk: { var out = self.extendList(pass[0]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk self.keepList(&out); },
            59 => pass[1],
            60 => self.list(pass),
            61 => self.sexp(.@"error_union", &.{pass[1]}),
            62 => self.sexp(.@"?", &.{pass[1]}),
            63 => self.sexp(.@"ptr", &.{pass[1]}),
            64 => self.sexp(.@"const_ptr", &.{pass[2]}),
            65 => self.sexp(.@"volatile_ptr", &.{pass[2]}),
            66 => self.sexp(.@"slice", &.{pass[2]}),
            67 => self.sexp(.@"sentinel_slice", &.{pass[2], pass[4]}),
            68 => self.sexp(.@"array_type", &.{pass[1], pass[3]}),
            69 => self.sexp(.@"many_ptr", &.{pass[3]}),
            70 => self.sexp(.@"sentinel_ptr", &.{pass[3], pass[5]}),
            71 => self.spreadList(pass[0], pass[1]),
            72 => self.spreadList(pass[1], pass[2]),
            73 => .{ .list = &[_]Sexp{} },
            74 => self.sexp(.@"fn_type", &.{pass[2], pass[4]}),
            75 => self.sexp(.@"fn_type", &.{.nil, pass[3]}),
            76 => self.list(pass),
            77 => self.list(pass),
            78 => self.list(pass),
            79 => self.list(pass),
            80 => self.list(pass),
            81 => self.list(pass),
            82 => self.list(pass),
            83 => self.list(pass),
            84 => self.list(pass),
            85 => self.list(pass),
            86 => self.list(pass),
            87 => self.list(pass),
            88 => self.list(pass),
            89 => self.list(pass),
            90 => self.list(pass),
            91 => self.list(pass),
            92 => self.list(pass),
            93 => self.list(pass),
            94 => self.sexp(.@"as", &.{pass[0], pass[2]}),
            95 => self.sexp(.@"as", &.{pass[0], pass[2]}),
            96 => self.sexp(.@"if", &.{pass[1], pass[2], pass[5], pass[6]}),
            97 => self.sexp(.@"if", &.{pass[1], pass[2], pass[5], pass[6]}),
            98 => self.sexp(.@"if", &.{pass[1], pass[2], pass[4]}),
            99 => self.sexp(.@"if", &.{pass[1], pass[2], pass[4]}),
            100 => self.sexp(.@"if", &.{pass[1], pass[2]}),
            101 => self.sexp(.@"while", &.{pass[1], .nil, pass[2], pass[4]}),
            102 => self.sexp(.@"while", &.{pass[1], pass[3], pass[4], pass[6]}),
            103 => self.sexp(.@"while", &.{pass[1], .nil, pass[2]}),
            104 => self.sexp(.@"while", &.{pass[1], pass[3], pass[4]}),
            105 => self.sexp(.@"for_ptr", &.{pass[2], .nil, pass[4], pass[5], pass[7]}),
            106 => self.sexp(.@"for_ptr", &.{pass[2], pass[4], pass[6], pass[7], pass[0]}),
            107 => self.sexp(.@"for", &.{pass[1], .nil, pass[3], pass[4], pass[6]}),
            108 => self.sexp(.@"for", &.{pass[1], pass[3], pass[5], pass[6], pass[8]}),
            109 => self.sexp(.@"for_ptr", &.{pass[2], .nil, pass[4], pass[5]}),
            110 => self.sexp(.@"for_ptr", &.{pass[2], pass[4], pass[6], pass[7]}),
            111 => self.sexp(.@"for", &.{pass[1], .nil, pass[3], pass[4]}),
            112 => self.sexp(.@"for", &.{pass[1], pass[3], pass[5], pass[6]}),
            113 => self.sexpPosSpread(.@"match", pass[1], pass[3]),
            114 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), pass[0]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk .{ .list = out.toOwnedSlice(self.allocator()) catch &[_]Sexp{} }; },
            115 => blk: { var out = self.extendList(pass[0]) catch break :blk .nil; out.append(self.allocator(), pass[2]) catch break :blk .nil; while (out.items.len > 0 and out.items[out.items.len - 1] == .nil) _ = out.pop(); break :blk self.keepList(&out); },
            116 => pass[0],
            117 => self.list(pass),
            118 => self.sexp(.@"enum_pattern", &.{pass[1]}),
            119 => self.list(pass),
            120 => self.sexp(.@"range_pattern", &.{pass[0], pass[2]}),
            121 => self.sexp(.@"arm", &.{pass[0], pass[2], pass[4]}),
            122 => self.sexp(.@"arm", &.{pass[0], pass[2], pass[3]}),
            123 => self.sexp(.@"arm", &.{pass[0], .nil, pass[2]}),
            124 => self.sexp(.@"arm", &.{pass[0], .nil, pass[1]}),
            125 => self.sexp(.@"ternary", &.{pass[2], pass[0], pass[4]}),
            126 => self.sexp(.@"if", &.{pass[2], pass[0]}),
            127 => self.sexp(.@"ternary", &.{pass[2], pass[0], pass[4]}),
            128 => self.sexp(.@"??", &.{pass[0], pass[2]}),
            129 => self.sexp(.@"catch", &.{pass[0], pass[3], pass[4]}),
            130 => self.sexp(.@"catch", &.{pass[0], pass[2]}),
            131 => self.sexp(.@"return", &.{pass[1], pass[3]}),
            132 => self.sexp(.@"return", &.{.nil, pass[2]}),
            133 => self.sexp(.@"return", &.{pass[1]}),
            134 => self.sexp(.@"return", &.{}),
            135 => self.sexp(.@"break", &.{.nil, pass[2], pass[4]}),
